package com.ianblk.zianmobs;
import java.util.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
/** Actual server damage paths sampled at every animation tick, plus interrupted windups. */
final class CompanionAttackSmoke {
 private static void check(boolean ok,String reason){if(!ok)throw new IllegalStateException(reason);}
 private static net.minecraft.world.entity.animal.Cow target(ServerPlayer p){var c=EntityType.COW.create(p.serverLevel());c.moveTo(p.getX()+4,p.getY(),p.getZ(),0,0);c.setNoAi(true);c.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);c.setHealth(100);p.serverLevel().addFreshEntity(c);p.setLastHurtMob(c);return c;}
 static void run(ServerPlayer p,Companions service){var previousClock=service.clock;long[] now={System.currentTimeMillis()+1000000};service.clock=()->now[0];try{
 check(CompanionAttacks.PROFILES.size()==16,"Source attack catalog incomplete");for(var entry:CompanionAttacks.PROFILES.entrySet()){String id=entry.getKey();now[0]+=60000;service.grant(p.getUUID(),id,Long.MAX_VALUE);service.summon(p,id);var pet=service.activeEntity(p.getUUID());pet.moveTo(p.getX()+1,p.getY(),p.getZ());var victim=target(p);try{service.attack(pet,p);var task=pet.pendingAttack;check(task!=null&&victim.getHealth()==100,"Damage occurred before animation: "+id);long deadline=service.life(p.getUUID(),id).attackAt();check(deadline==now[0]+4000,"Windup did not reserve persisted cooldown");for(int tick=1;tick<=task.profile.duration();tick++){float before=victim.getHealth();victim.invulnerableTime=Math.max(0,victim.invulnerableTime-1);pet.tickCount=task.started+tick;service.advanceAttack(pet,p);final int at=tick;check(task.released==task.profile.impacts().stream().filter(t->t<=at).count(),"Attack marker drift: "+id+" tick "+tick);if(!task.profile.impacts().contains(tick))check(victim.getHealth()==before,"Damage outside release marker: "+id);float after=victim.getHealth();service.advanceAttack(pet,p);check(victim.getHealth()==after,"Release duplicated in the same tick");}check(pet.pendingAttack==null&&victim.getHealth()<100&&100-victim.getHealth()<=service.effective(p.getUUID(),id).attackDamage()+.01,"Recovery or volley damage budget failed: "+id);float hp=victim.getHealth();service.attack(pet,p);check(pet.pendingAttack==null&&victim.getHealth()==hp,"Repeated cast bypassed cooldown");service.store(p.getUUID(),false);service.summon(p,id);check(service.activeEntity(p.getUUID()).pendingAttack==null&&service.life(p.getUUID(),id).attackAt()==deadline,"Resummon reset pending attack or cooldown");}finally{victim.discard();service.store(p.getUUID(),false);}}
 for(String interruption:List.of("distance","dead","store","revoke","wall")){now[0]+=60000;String id="cubee_cannon";service.grant(p.getUUID(),id,Long.MAX_VALUE);service.summon(p,id);var pet=service.activeEntity(p.getUUID());pet.moveTo(p.getX()+1,p.getY(),p.getZ());var victim=target(p);var blocks=new LinkedHashMap<net.minecraft.core.BlockPos,net.minecraft.world.level.block.state.BlockState>();try{service.attack(pet,p);check(pet.pendingAttack!=null,"Interruption did not prepare attack");switch(interruption){case "distance"->victim.moveTo(p.getX()+30,p.getY(),p.getZ());case "dead"->victim.discard();case "store"->service.store(p.getUUID(),false);case "revoke"->{service.grant(p.getUUID(),id,0);service.checkAccess(p);}case "wall"->{for(int y=0;y<3;y++){var pos=net.minecraft.core.BlockPos.containing(p.getX()+2,p.getY()+y,p.getZ());blocks.put(pos,p.serverLevel().getBlockState(pos));p.serverLevel().setBlockAndUpdate(pos,net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());}}}pet.tickCount+=50;service.advanceAttack(pet,p);check(pet.pendingAttack==null&&victim.getHealth()==100,"Interrupted attack still damaged target: "+interruption);}finally{blocks.forEach((pos,state)->p.serverLevel().setBlockAndUpdate(pos,state));victim.discard();service.store(p.getUUID(),false);}}
 }finally{service.store(p.getUUID(),false);service.clock=previousClock;p.setLastHurtMob(null);}}
 private CompanionAttackSmoke(){}
}
